        "testata": "BBC News",
        "lingua_originale": "en",
        "titolo_orig": "Five takeaways from the King's historic address to Congress",
        "testo_it": "Re Carlo III tiene un discorso storico al Congresso USA durante la sua visita ufficiale.",
        "priorita": "Media",
